SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_0223 AS DOUBLE PRECISION) AS metric_0223, CAST(metric_0445 AS DOUBLE PRECISION) AS metric_0445, CAST(metric_0667 AS DOUBLE PRECISION) AS metric_0667, CAST(metric_0889 AS DOUBLE PRECISION) AS metric_0889, CAST(metric_1111 AS DOUBLE PRECISION) AS metric_1111, CAST(metric_1333 AS DOUBLE PRECISION) AS metric_1333, CAST(metric_1555 AS DOUBLE PRECISION) AS metric_1555, CAST(metric_1777 AS DOUBLE PRECISION) AS metric_1777, CAST(metric_2000 AS DOUBLE PRECISION) AS metric_2000 FROM wide2000 PREWHERE time >= '2024-09-23' AND time < '2025-01-01' ORDER BY time
